n_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6beee1f9-6f58-5c4d-b8d3-8ab9803bd46f"}, {"title": "盖寓领容管观察使", "start_year": 895, "end_year": 895, "time_original": "895年十二月乙未", "dynasty": "唐", "description": "朝廷以河东大将盖寓领容管观察使。", "phases": [], "location_name": "容管", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4ed2e64b-4e7c-57e2-8e15-af28f639fade"}, {"title": "李克用其余将佐子孙进官爵", "start_year": 895, "end_year": 895, "time_original": "895年十二月乙未条", "dynasty": "唐", "description": "李克用其余将佐、子孙也进官爵。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c1a004cb-b7ab-577a-9ec5-5e2f06833412"}, {"title": "朱温屡间李克用盖寓，李克用待寓更厚", "start_year": null, "end_year": null, "time_original": "卷260乾宁二年条背景；数次离间起讫未载", "dynasty": "唐", "description": "朱温多次派人离间李克用与盖寓，并扬言盖寓已取代李克用，李克用却对盖寓更优厚。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d2b253c3-dc4d-520d-b641-ba39d581593d"}, {"title": "王建攻东川，王宗弼被擒", "start_year": 895, "end_year": 895, "time_original": "895年十二月丙申", "dynasty": "唐", "description": "王建进攻东川，别将王宗弼被东川军俘获。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5186d486-b1fc-5f21-9dba-1c18a87a92ba"}, {"title": "顾彦晖将被俘王宗弼收为子", "start_year": 895, "end_year": 895, "time_original": "895年十二月丙申被俘后条；确日未另载", "dynasty": "唐", "description": "顾彦晖将王宗弼收养为子。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7718ac03-6268-50d1-8cd0-7b0f7026783f"}, {"title": "通州李彦昭率二千兵降王建", "start_year": 895, "end_year": 895, "time_original": "895年十二月戊戌", "dynasty": "唐", "description": "通州刺史李彦昭率所部二千人降王建。", "phases": [], "location_name": "通州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4eb070b0-2499-5a57-ae35-0af921976685"}]'::jsonb)
